def compute(vars):
    cash_and_cash_equivalents = vars["Cash and Cash Equivalents"]
    short_term_investments = vars["Short-term Investments"]
    accounts_receivable = vars["Accounts Receivable"]
    current_liabilities = vars["Current Liabilities"]

    if current_liabilities == 0:
        return None

    quick_assets = (
        cash_and_cash_equivalents
        + short_term_investments
        + accounts_receivable
    )
    quick_ratio = quick_assets / current_liabilities

    return {
        "value": quick_ratio,
        "trace": {
            "Cash and Cash Equivalents": cash_and_cash_equivalents,
            "Short-term Investments": short_term_investments,
            "Accounts Receivable": accounts_receivable,
            "Current Liabilities": current_liabilities,
            "Quick Assets": quick_assets,
            "output_meta": {
                "currency": "$",
                "scale": None,
                "unit": None
            }
        }
    }

